using System;using System.Reflection;
class Test52Uv {
static int n;static void Check(bool ok,string reason){if(!ok)throw new Exception(reason);n++;}
static void Main(){var a=Assembly.LoadFrom("MedianGrassReplacement.dll");var policy=a.GetType("MedianGrassReplacement.Systems.GlobalSurfacePolicy");var f=BindingFlags.NonPublic|BindingFlags.Static;foreach(var pair in new[]{new object[]{"RoadUv",.01f,1f,.16f},new object[]{"SidewalkTiling",.1f,10f,1f}}){var m=policy.GetMethod((string)pair[0],f);foreach(var value in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity,-10f,0f,.5f,100f}){float result=(float)m.Invoke(null,new object[]{value});Check(!float.IsNaN(result)&&!float.IsInfinity(result)&&result>=(float)pair[1]&&result<=(float)pair[2],"UV settings finite and bounded");if(float.IsNaN(value)||float.IsInfinity(value))Check(result==(float)pair[3],"invalid UV returns recommended default");}}var asset=policy.GetMethod("AssetKind",f);foreach(var name in new[]{"AsphaltSurface","Pavement Area","ParkingLotSurface"})Check((int)asset.Invoke(null,new object[]{name,"BH/AreaDecalShader"})==4,"asset asphalt uses road base-color channel");Check((int)asset.Invoke(null,new object[]{"Sidewalk","BH/AreaDecalShader"})==2,"asset sidewalk uses sidewalk channel");foreach(var name in new[]{"RoadParts","RoadWear","Grass","Rail","Arrow"})Check((int)asset.Invoke(null,new object[]{name,"BH/AreaDecalShader"})==0,"protected asset category retained");Check((int)asset.Invoke(null,new object[]{"AsphaltSurface","BuildingShader"})==0,"building shader not treated as pavement");var settings=a.GetType("MedianGrassReplacement.Setting");var instance=System.Runtime.Serialization.FormatterServices.GetUninitializedObject(settings);settings.GetMethod("SetSurfaceDefaults",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(instance,null);Check((string)settings.GetProperty("GlobalRoadTexture").GetValue(instance)=="__CURBSIDE_ROAD__"&&(string)settings.GetProperty("GlobalSidewalkTexture").GetValue(instance)=="__CURBSIDE_SIDEWALK__","direct global defaults use supplied images");settings.GetProperty("SidewalkTextureA").SetValue(instance,"local-test.png");Check((string)settings.GetProperty("GlobalSidewalkTexture").GetValue(instance)=="__CURBSIDE_SIDEWALK__","legacy local preference cannot change global selection");Check(Math.Abs((float)settings.GetProperty("RoadSurfaceUv").GetValue(instance)-.16f)<.0001f&&(float)settings.GetProperty("SidewalkSurfaceTiling").GetValue(instance)==1f,"independent UV defaults");Console.WriteLine(n+" independent UV range/default checks passed");}}
